  font-weight: 600;
}

.header {
  padding: 12px 20px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  text-align: center;
}

.title {
  font-size: 28px;
  font-weight: 800;
  color: var(--color-text);
}

.subtitle {
  font-size: 15px;
  color: var(--color-text-secondary);
}

.content {
  padding: 0 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.button {
  background: var(--color-accent);
  border-radius: 12px;
  padding: 16px;
  align-items: center;
  justify-content: center;
